Method.Implementation:
	set stat = $$$OK

	$$$TRACE("In ProcessCoreMessageRequest: " _ x12MsgReq)

	set pHttpRequest = ##class(EnsLib.HTTP.GenericMessage).%New()

	Set tStream = ##class(%Stream.GlobalBinary).%New()
    set jsonStr = {"COREEnvelopeRealTimeRequest":
    {"Payload":(x12MsgReq.Payload), 
    "TtUniqueId": (x12MsgReq.TtUniqueId), 
    "Source": (x12MsgReq.TtDataSource),
    "InterchangeReceiverID":(x12MsgReq.ReceiverID),
    "InterchangeSenderID":(x12MsgReq.SenderID),
    "InterchangeControlNumber":(x12MsgReq.ControlNumber),
    "ProcessingMode": (x12MsgReq.PayloadType),
    "TtTimeStamp": (x12MsgReq.TimeStamp),
    "TtMsgType": (x12MsgReq.TtMsgType),
    "TM":(..UseTM),
    "Reply" : "27xData"
    } }.%ToJSON(.tStream)

		Do pHttpRequest.HTTPHeaders.SetAt("application/json","content-type")
		Do pHttpRequest.HTTPHeaders.SetAt(tStream.Size,"content-length")
		Set pHttpRequest.Stream = ##class(%Stream.GlobalBinary).%New()
		Set tStatus = pHttpRequest.Stream.CopyFrom(tStream)
		$$$ThrowOnError(tStatus)

		Do tStream.Rewind()
		Set tStr = tStream.Read()
		$$$TRACE("Data string: " _ tStr)

	set pResp = ##class(Ens.StringContainer).%New()	
	set callStat = $$$OK
	try
	{
		set callStat = ..OnMessage(pHttpRequest, .pResponse)
	}
	catch (er)
	{
		set pResp.StringValue = "Exception: " + er.Data
		$$$TRACE("Exception in OnMessage: " _ er)
	}

	if ($$$ISOK(callStat)) {
		Do pResponse.Stream.Rewind()
		set pResp.StringValue = ""
		$$$TRACE("pResponse.Stream Length: " _ pResponse.Stream.Size)
		if (pResponse.Stream.Size = 0)
		{
			set stat = $$$ERROR("Web Service returned 0 bytes")
		}
		else
		{
			While (pResponse.Stream.AtEnd = 0) {
		    	Set len = 10000
		    	set pResp.StringValue = pResp.StringValue _ pResponse.Stream.Read(.len)
		    	$$$TRACE(pResp.StringValue)
	    	}
	    	if (pResp.StringValue [ "HTTP ERROR: 404")
	    	{
		    	set stat = $$$ERROR("Web Service not running" _ pResp.StringValue)
	    	}
		}	    
	}
	else
	{
		set pResp.StringValue = "Error in calling Edifecs: " + callStat
	}
    return stat

Set tProperty = ""  For { Set tProperty = $$$comMemberNext(%class,$$$cCLASSproperty,tProperty)  Quit:""=tProperty
	// Look for datatypes that are of type Ens.DataType.ConfigName, or a subclass
	$$$comMemberKeyGetLvar(tRuntimeType,%class,$$$cCLASSproperty,tProperty,$$$cPROPruntimetype)
	If ($$$getClassType(tRuntimeType)=$$$cCLASSCLASSTYPEDATATYPE)
	 && ((tRuntimeType="Ens.DataType.ConfigName") || $$IsDerivedFrom^%occLibrary(tRuntimeType,"Ens.DataType.ConfigName")) {
		$$$GENERATE("	If pItem.GetModifiedSetting("""_tProperty_""",.tValue) Do:tValue'="""" ..makeConnections(tValue,.pArray,"""_tRuntimeType_""")")
	}
}
$$$GENERATE("	If pItem.GetModifiedSetting(""AlertOnError"",.tValue),+tValue { Set pArray(""Ens.Alert"")="""" }")
$$$GENERATE("	ElseIf pItem.GetModifiedSetting(""AlertOnError"",.tValue) { Kill pArray(""Ens.Alert"") }")
$$$GENERATE("	Quit")
Quit $$$OK

For i=1:1:$L(pConfigNames,",") {
	Set tConfigName = $ZStrip($P(pConfigNames,",",i),"<>W")

	// For ConfigNames that use template replacement, don't include them unless it's a canonical value
	Continue:pConfigNameType="Ens.DataType.ConfigNameTemplate"&&'##class(Ens.DataType.ConfigNameTemplate).IsCanonical(tConfigName)

	Set:tConfigName'="" pArray(tConfigName)=""
}
